ALTER TABLE public.events ADD COLUMN IF NOT EXISTS category text NOT NULL DEFAULT 'NSW Training', ADD COLUMN IF NOT EXISTS city text NOT NULL DEFAULT '', ADD COLUMN IF NOT EXISTS trainer text NOT NULL DEFAULT '', ADD COLUMN IF NOT EXISTS reg_open date NOT NULL DEFAULT CURRENT_DATE, ADD COLUMN IF NOT EXISTS reg_close date, ADD COLUMN IF NOT EXISTS objectives text[] NOT NULL DEFAULT '{}', ADD COLUMN IF NOT EXISTS audience text NOT NULL DEFAULT '', ADD COLUMN IF NOT EXISTS requirements text[] NOT NULL DEFAULT '{}', ADD COLUMN IF NOT EXISTS additional_info text NOT NULL DEFAULT '', ADD COLUMN IF NOT EXISTS approval_required boolean NOT NULL DEFAULT false;
ALTER TABLE public.registrations ADD COLUMN IF NOT EXISTS reference text, ADD COLUMN IF NOT EXISTS organisation text NOT NULL DEFAULT '', ADD COLUMN IF NOT EXISTS attendance_status text;
CREATE SEQUENCE IF NOT EXISTS public.registration_reference_seq;
UPDATE public.registrations SET reference = 'NSW-TRN-' || EXTRACT(YEAR FROM created_at)::text || '-' || lpad(nextval('public.registration_reference_seq')::text,5,'0') WHERE reference IS NULL;
CREATE UNIQUE INDEX IF NOT EXISTS registrations_reference_unique ON public.registrations(reference);
CREATE TABLE public.profiles (id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE, display_name text NOT NULL DEFAULT '', avatar_url text NOT NULL DEFAULT '', preferences jsonb NOT NULL DEFAULT '{}', updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE ON public.profiles TO authenticated;
GRANT ALL ON public.profiles TO service_role;
ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Own profile select" ON public.profiles FOR SELECT TO authenticated USING (id=auth.uid());
CREATE POLICY "Own profile insert" ON public.profiles FOR INSERT TO authenticated WITH CHECK(id=auth.uid());
CREATE POLICY "Own profile update" ON public.profiles FOR UPDATE TO authenticated USING(id=auth.uid()) WITH CHECK(id=auth.uid());
CREATE FUNCTION public.create_admin_profile() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO public.profiles(id,display_name) VALUES(NEW.id,coalesce(NEW.raw_user_meta_data->>'name','')) ON CONFLICT DO NOTHING; RETURN NEW; END $$;
CREATE TRIGGER create_admin_profile_on_signup AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION public.create_admin_profile();
INSERT INTO public.profiles(id) SELECT id FROM auth.users ON CONFLICT DO NOTHING;
CREATE TABLE public.venues (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, address text NOT NULL DEFAULT '', city text NOT NULL DEFAULT '', capacity integer NOT NULL DEFAULT 50, status text NOT NULL DEFAULT 'available');
GRANT SELECT,INSERT,UPDATE,DELETE ON public.venues TO authenticated;
GRANT ALL ON public.venues TO service_role;
ALTER TABLE public.venues ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Admins manage venues" ON public.venues FOR ALL TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin'));
CREATE TABLE public.communication_drafts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), event_id uuid REFERENCES public.events(id), subject text NOT NULL, body text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), status text NOT NULL DEFAULT 'draft');
GRANT SELECT,INSERT,UPDATE,DELETE ON public.communication_drafts TO authenticated;
GRANT ALL ON public.communication_drafts TO service_role;
ALTER TABLE public.communication_drafts ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Admins manage communications" ON public.communication_drafts FOR ALL TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin'));
DROP POLICY IF EXISTS "Users can view own registrations" ON public.registrations;
DROP POLICY IF EXISTS "Anyone can register" ON public.registrations;
DROP POLICY IF EXISTS "Anyone can view attendance" ON public.attendance;
REVOKE ALL ON public.registrations,public.attendance FROM anon;
GRANT SELECT,INSERT,UPDATE,DELETE ON public.events,public.registrations,public.attendance TO authenticated;
GRANT SELECT ON public.events TO anon;
GRANT ALL ON public.events,public.registrations,public.attendance,public.user_roles TO service_role;
GRANT SELECT ON public.user_roles TO authenticated;
CREATE POLICY "Users read their roles" ON public.user_roles FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE FUNCTION public.event_availability() RETURNS TABLE(event_id uuid, registered bigint) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT e.id,count(r.id) FROM public.events e LEFT JOIN public.registrations r ON r.event_id=e.id AND r.status NOT IN ('rejected','cancelled') WHERE e.status='published' GROUP BY e.id $$;
REVOKE ALL ON FUNCTION public.event_availability() FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.event_availability() TO anon,authenticated;
CREATE FUNCTION public.register_for_training(p_event_id uuid,p_name text,p_email text,p_phone text,p_organisation text,p_role text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE ev public.events; rid uuid; ref text; total bigint; normalized text:=lower(trim(p_email)); regstatus text; BEGIN
IF length(trim(p_name))<2 OR length(p_name)>120 OR normalized !~ '^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$' OR length(normalized)>254 OR p_phone !~ '^\+?[0-9 ()-]{7,25}$' OR length(regexp_replace(p_phone,'[^0-9]','','g'))<7 OR length(trim(p_organisation))<2 OR length(p_organisation)>150 OR length(trim(p_role))<2 OR length(p_role)>120 THEN RAISE EXCEPTION 'Please provide valid name, email, phone, organisation and designation.'; END IF;
SELECT * INTO ev FROM public.events WHERE id=p_event_id FOR UPDATE;
IF NOT FOUND OR ev.status<>'published' THEN RAISE EXCEPTION 'Training is not available for registration.'; END IF;
IF EXISTS(SELECT 1 FROM public.registrations WHERE event_id=p_event_id AND lower(trim(email))=normalized) THEN RAISE EXCEPTION 'You are already registered for this training.'; END IF;
IF (now() AT TIME ZONE 'Africa/Lagos')::date<ev.reg_open THEN RAISE EXCEPTION 'Registration has not opened.'; END IF;
IF (now() AT TIME ZONE 'Africa/Lagos')::date>coalesce(ev.reg_close,ev.event_date) OR ev.event_date<(now() AT TIME ZONE 'Africa/Lagos')::date THEN RAISE EXCEPTION 'Registration has closed.'; END IF;
SELECT count(*) INTO total FROM public.registrations WHERE event_id=p_event_id AND status NOT IN ('rejected','cancelled');
IF total>=ev.total_slots THEN RAISE EXCEPTION 'This training is fully booked.'; END IF;
ref:='NSW-TRN-' || EXTRACT(YEAR FROM now())::text || '-' || lpad(nextval('public.registration_reference_seq')::text,5,'0');
regstatus:=CASE WHEN ev.approval_required THEN 'pending' ELSE 'confirmed' END;
INSERT INTO public.registrations(event_id,first_name,last_name,email,phone,participation_type,role,experience_level,organisation,business_name,status,reference) VALUES(p_event_id,split_part(trim(p_name),' ',1),coalesce(nullif(substring(trim(p_name) from position(' ' in trim(p_name))+1),trim(p_name)),''),normalized,trim(p_phone),'individual',trim(p_role),'not_specified',trim(p_organisation),trim(p_organisation),regstatus,ref) RETURNING id INTO rid;
RETURN jsonb_build_object('id',rid,'reference',ref,'status',regstatus,'email',normalized);
END $$;
REVOKE ALL ON FUNCTION public.register_for_training(uuid,text,text,text,text,text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.register_for_training(uuid,text,text,text,text,text) TO anon,authenticated;
CREATE FUNCTION public.validate_training_rules() RETURNS trigger LANGUAGE plpgsql AS $$ DECLARE taken bigint; BEGIN IF NEW.total_slots<1 OR NEW.total_slots>10000 THEN RAISE EXCEPTION 'Capacity must be between 1 and 10000.'; END IF; IF NEW.end_time IS NOT NULL AND NEW.end_time<=NEW.start_time THEN RAISE EXCEPTION 'End time must be after start time.'; END IF; IF NEW.reg_close IS NOT NULL AND (NEW.reg_close<NEW.reg_open OR NEW.reg_close>NEW.event_date) THEN RAISE EXCEPTION 'Registration dates must be ordered and close by the training date.'; END IF; SELECT count(*) INTO taken FROM public.registrations WHERE event_id=NEW.id AND status NOT IN ('rejected','cancelled'); IF NEW.total_slots<taken THEN RAISE EXCEPTION 'Capacity cannot be lower than existing registrations.'; END IF; RETURN NEW; END $$;
CREATE TRIGGER validate_training_rules BEFORE INSERT OR UPDATE ON public.events FOR EACH ROW EXECUTE FUNCTION public.validate_training_rules();